  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-primary);
  letter-spacing: -.02em;
}

/* ── Layout ───────────────────────────────────────────────────────── */
.container {
  width: 100%;
  max-width: 480px;
  margin-inline: auto;
  padding-inline: 1.25rem;
}

main.container { padding-block: 3rem 4rem; }

/* ── Card ─────────────────────────────────────────────────────────── */
.form-card {
  background: var(--color-surface);
  border-radius: calc(var(--radius) * 2);
  box-shadow: var(--shadow-card);
  padding: 2.5rem 2rem;
}

@media (max-width: 480px) {
  .form-card { padding: 2rem 1.25rem; }
}

.form-card__intro { margin-bottom: 2rem; }

.form-card__intro h1 {
  font-size: 1.625rem;
