+/* ── Reset & base ─────────────────────────────────────────────────── */
+*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+
+:root {
+  --color-bg:           #f5f6fa;
+  --color-surface:      #ffffff;
+  --color-primary:      #4f46e5;
+  --color-primary-dark: #3730a3;
+  --color-primary-hover:#4338ca;
+  --color-text:         #111827;
+  --color-muted:        #6b7280;
+  --color-border:       #d1d5db;
+  --color-border-focus: #4f46e5;
+  --color-error:        #b91c1c;
+  --color-error-bg:     #fef2f2;
+  --color-error-border: #fca5a5;
+  --color-hint:         #6b7280;
+  --color-success-bg:   #f0fdf4;
+  --color-success-border:#86efac;
+  --color-success-text: #15803d;
+  --radius:             8px;
+  --shadow-card:        0 1px 3px rgba(0,0,0,.10), 0 4px 16px rgba(0,0,0,.06);
+  --transition:         150ms ease;
+  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
+}
+
+body {
+  font-family: var(--font);
+  background: var(--color-bg);
+  color: var(--color-text);
+  min-height: 100dvh;
+  line-height: 1.5;
+}
+
+/* ── Skip link ────────────────────────────────────────────────────── */
+.skip-link {
+  position: absolute;
+  top: -999px;
+  left: 1rem;
+  padding: .5rem 1rem;
+  background: var(--color-primary);
+  color: #fff;
+  border-radius: var(--radius);
+  font-weight: 600;
+  text-decoration: none;
+  z-index: 100;
+  outline-offset: 2px;
+}
+.skip-link:focus { top: 1rem; }
+
+/* ── Site header ──────────────────────────────────────────────────── */
+.site-header {
+  background: var(--color-surface);
+  border-bottom: 1px solid var(--color-border);
+  padding: 1rem 0;
+}
+.logo {
+  font-size: 1.125rem;
+  font-weight: 700;
+  color: var(--color-primary);
+  letter-spacing: -.02em;
+}
+
+/* ── Layout ───────────────────────────────────────────────────────── */
+.container {
+  width: 100%;
+  max-width: 480px;
+  margin-inline: auto;
+  padding-inline: 1.25rem;
+}
+
+main.container { padding-block: 3rem 4rem; }
+
+/* ── Card ─────────────────────────────────────────────────────────── */
+.form-card {
+  background: var(--color-surface);
+  border-radius: calc(var(--radius) * 2);
+  box-shadow: var(--shadow-card);
+  padding: 2.5rem 2rem;
+}
+
+@media (max-width: 480px) {
+  .form-card { padding: 2rem 1.25rem; }
+}
+
+.form-card__intro { margin-bottom: 2rem; }
+
+.form-card__intro h1 {
+  font-size: 1.625rem;
+  font-weight: 700;
+  letter-spacing: -.03em;
+  margin-bottom: .5rem;
+}
+
+.form-card__intro p {
+  color: var(--color-muted);
+  font-size: .9375rem;
+}
+
+/* ── Status message ───────────────────────────────────────────────── */
+.status-message {
+  border-radius: var(--radius);
+  font-size: .9375rem;
+  font-weight: 500;
+  padding: .875rem 1rem;
+  margin-bottom: 1.5rem;
+  display: none;
+}
+.status-message.is-success {
+  display: block;
+  background: var(--color-success-bg);
+  border: 1px solid var(--color-success-border);
+  color: var(--color-success-text);
+}
+.status-message.is-error {
+  display: block;
+  background: var(--color-error-bg);
+  border: 1px solid var(--color-error-border);
+  color: var(--color-error);
+}
+
+/* ── Form ─────────────────────────────────────────────────────────── */
+form { display: flex; flex-direction: column; gap: 1.25rem; }
+
+/* ── Form field ───────────────────────────────────────────────────── */
+.form-field { display: flex; flex-direction: column; gap: .375rem; }
+
+label {
+  font-size: .9375rem;
+  font-weight: 600;
+  color: var(--color-text);
+}
+
+.required-mark { color: var(--color-error); margin-left: .125rem; }
+
+input {
+  width: 100%;
+  padding: .625rem .875rem;
+  font-family: var(--font);
+  font-size: 1rem;
+  color: var(--color-text);
+  background: var(--color-surface);
+  border: 1.5px solid var(--color-border);
+  border-radius: var(--radius);
+  transition: border-color var(--transition), box-shadow var(--transition);
+  outline: none;
+  min-width: 0;
+}
+
+input::placeholder { color: #9ca3af; }
+
+input:hover:not(:focus):not([aria-invalid="true"]) {
+  border-color: #9ca3af;
+}
+
+input:focus {
+  border-color: var(--color-border-focus);
+  box-shadow: 0 0 0 3px rgba(79, 70, 229, .25);
+  outline: 2px solid transparent;
+}
+
+input[aria-invalid="true"] {
+  border-color: var(--color-error-border);
+  background: var(--color-error-bg);
+}
+
+input[aria-invalid="true"]:focus {
+  border-color: var(--color-error);
+  box-shadow: 0 0 0 3px rgba(185, 28, 28, .2);
+}
+
+/* ── Helper / error text ──────────────────────────────────────────── */
+.field-hint {
+  font-size: .8125rem;
+  color: var(--color-hint);
+}
+
+.field-error {
+  font-size: .8125rem;
+  color: var(--color-error);
+  font-weight: 500;
+  min-height: 0;
+}
+
+/* hidden until validation fires */
+.field-error:empty { display: none; }
+
+/* ── Submit button ────────────────────────────────────────────────── */
+.btn-submit {
+  margin-top: .5rem;
+  padding: .75rem 1.5rem;
+  font-family: var(--font);
+  font-size: 1rem;
+  font-weight: 600;
+  color: #fff;
+  background: var(--color-primary);
+  border: none;
+  border-radius: var(--radius);
+  cursor: pointer;
+  transition: background var(--transition), box-shadow var(--transition);
+  outline-offset: 3px;
+}
+
+.btn-submit:hover { background: var(--color-primary-hover); }
+
+.btn-submit:focus-visible {
+  outline: 2px solid var(--color-primary);
+  box-shadow: 0 0 0 4px rgba(79, 70, 229, .3);
+}
+
+.btn-submit:active { background: var(--color-primary-dark); }
+
+/* ── Screen-reader only ───────────────────────────────────────────── */
+.sr-only {
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  padding: 0;
+  margin: -1px;
+  overflow: hidden;
+  clip: rect(0,0,0,0);
+  white-space: nowrap;
+  border: 0;
+}
+
+/* ── Forced colors / high contrast ───────────────────────────────── */
